 INSERT
   INTO
        TB_TRAVEL
        (
        TRAVEL_NO
      , REGION_NO
      , TRAVEL_NAME
      , TRAVEL_CONTENT
      , TRAVEL_ADDRESS
      , MAP_X
      , MAP_Y
      , TRAVEL_IMAGE
      , TRAVEL_STATUS
      , COUNT
 ) 
VALUES 
     (
       SEQ_TRAVEL.NEXTVAL
     , #{regionNo}
     , #{travelName}
     , #{travelContent}
     , #{travelAddress}
     , #{mapX}
     , #{mapY}
     , #{travelImage}
     , 'N'
     , 0    
     )
